-- B-tree index: supports =, <, >, BETWEEN, LIKE 'prefix%'
CREATE INDEX idx_orders_customer ON orders(customer_id);

-- Composite index: column order matters
-- Good for WHERE customer_id = ? AND status = ?
-- Also usable for WHERE customer_id = ? alone (leading column)
-- NOT usable for WHERE status = ? alone
CREATE INDEX idx_orders_customer_status ON orders(customer_id, status);

-- Covering index: avoids heap fetch entirely
-- Query: SELECT status, total FROM orders WHERE customer_id = ?
CREATE INDEX idx_orders_covering ON orders(customer_id) INCLUDE (status, total);

-- Partial index: only indexes rows matching a condition
CREATE INDEX idx_active_orders ON orders(customer_id)
WHERE status = 'ACTIVE';

-- Hash index: equality-only, faster for = but no range support
CREATE INDEX idx_session_token ON sessions USING HASH (token);

-- GIN index: for full-text search and JSONB
CREATE INDEX idx_products_tags ON products USING GIN (tags);

// JPA: declare indexes on the @Table annotation
@Entity
@Table(name = "orders",
    indexes = {
        @Index(name = "idx_orders_customer_status",
               columnList = "customer_id, status")
    })
public class Order {
    @Id private Long id;
    private Long customerId;
    private String status;
    private BigDecimal total;
}

