-- B-tree index (default): fast equality + range queries
CREATE INDEX idx_email ON users(email);
CREATE INDEX idx_status_created ON orders(status, created_at); -- composite

-- Composite index: leftmost prefix rule applies
-- This query USES the index (leftmost columns match)
SELECT * FROM orders WHERE status = 'PENDING' AND created_at > '2024-01-01';
-- This query also USES the index (leftmost column alone)
SELECT * FROM orders WHERE status = 'PENDING';
-- This query does NOT use the composite index efficiently (skips 'status')
SELECT * FROM orders WHERE created_at > '2024-01-01';

-- Full-text index: natural language search
CREATE FULLTEXT INDEX idx_ft_content ON articles(title, body);
SELECT * FROM articles
WHERE MATCH(title, body) AGAINST ('Spring Boot performance' IN NATURAL LANGUAGE MODE);

-- Hash index: only in MEMORY engine, exact equality only
-- InnoDB uses adaptive hash indexes internally (automatic)

-- Covering index: all needed columns are in the index itself
CREATE INDEX idx_covering ON orders(user_id, status, total);
-- The following query is served entirely from the index (no table lookup)
SELECT status, total FROM orders WHERE user_id = 42;

-- Spring Data JPA: @Index annotation maps to DB index
-- @Table(indexes = @Index(name = "idx_email", columnList = "email"))

